<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class DeliveryOrder extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','warehouse_id','fulfillment_id','sales_order_id','created_by','number','state','shipment_status','idempotency_key','carrier','carrier_service','tracking_number','tracking_url','planned_dispatch_date','expected_delivery_date','dispatched_at','dispatched_by','posted_at']; protected function casts():array{return ['planned_dispatch_date'=>'date','expected_delivery_date'=>'date','dispatched_at'=>'datetime','posted_at'=>'datetime'];} public function items(){return $this->hasMany(DeliveryOrderItem::class);} public function fulfillment(){return $this->belongsTo(SalesFulfillment::class,'fulfillment_id');} public function trackingEvents(){return $this->hasMany(ShipmentTrackingEvent::class,'delivery_order_id');} public function pod(){return $this->hasOne(ProofOfDeliveryRecord::class,'delivery_order_id');} public function exceptions(){return $this->hasMany(DeliveryException::class,'delivery_order_id');} }
